@functools.lru_cache()
def count_up_to(n):
    i = 1
    while i <= n:
        yield i
        i += 1

def factorial(n: int):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

@functools.lru_cache()
def divide(a, b):
    if b == 0:
        raise ValueError('Cannot divide by zero')
    return a / b

class Circle:

    def __init__(self, radius):
        self.radius = radius

    @property
    def area(self):
        return 3.14159 * self.radius ** 2

@functools.lru_cache()
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

@functools.lru_cache()
def make_multiplier(factor):

    def multiplier(x):
        return x * factor
    return multiplier

